//! 🔺️ create-image leaf-owned typed sparse operation diff.
use serde::{Deserialize, Serialize};
use crate::artifacts::gltf::GltfSnapshot;
use crate::artifacts::gltf::schema::snapshot::GltfImage;
use crate::artifacts::gltf::schema::diff::GltfDiff;
use crate::artifacts::gltf::schema::mutations::create_image::mutation::{apply, validate, GltfCreateImagePayload};
use crate::artifacts::gltf::schema::mutations::top_level_collections_private::{images_op, family_diff, reject, repair, Change, GltfTopLevelFamily, GltfTopLevelMutationRejection};
pub const ID: &str = "s.stdio.gltf.mutation.create-image.v1";
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(tag = "kind", rename_all = "camelCase")]
pub enum GltfCreateImageOperation { Insert { position: usize, item: GltfImage }, Delete { index: usize, removed: GltfImage }, Move { index: usize, position: usize }, Reorder { order: Vec<usize> } }
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(rename_all = "camelCase")]
pub struct GltfCreateImageDiff { pub id: String, pub version: u32, pub touched_paths: Vec<String>, pub payload: GltfCreateImagePayload, pub operation: GltfCreateImageOperation }
async fn operation(payload: &GltfCreateImagePayload, base: &GltfSnapshot) -> GltfCreateImageOperation { GltfCreateImageOperation::Insert { position: payload.position, item: GltfImage::default() } }
async fn touched_paths(payload: &GltfCreateImagePayload) -> Vec<String> { vec![format!("document/images/{}", payload.position)] }
pub async fn validate_diff(diff: &GltfCreateImageDiff, base: &GltfSnapshot) -> Result<(), GltfTopLevelMutationRejection> { if diff.id != ID || diff.version != 1 { return Err(reject("gltf.mutation.invalid-diff-envelope", "diff", "descriptor identity does not match")); } if diff.touched_paths != touched_paths(&diff.payload) { return Err(reject("gltf.mutation.invalid-touched-paths", "diff/touchedPaths", "paths must be concrete payload-derived locations")); } validate(&diff.payload, base)?; if diff.operation != operation(&diff.payload, base) { return Err(reject("gltf.mutation.invalid-sparse-operation", "diff/operation", "operation must equal the direct typed delta")); } Ok(()) }
pub async fn apply_diff(diff: &GltfCreateImageDiff, base: &GltfSnapshot) -> Result<GltfSnapshot, GltfTopLevelMutationRejection> { validate_diff(diff, base)?; let mut next = base.clone(); let operation = &diff.operation; match operation { GltfCreateImageOperation::Insert { position, item } => { repair(&mut next.document, GltfTopLevelFamily::Images, &Change::Insert(*position))?; next.document.images.insert(*position, item.clone());  }, GltfCreateImageOperation::Delete { index, .. } => { images_op(&mut next, GltfTopLevelFamily::Images, *index, None, None)?;  }, GltfCreateImageOperation::Move { index, position } => { images_op(&mut next, GltfTopLevelFamily::Images, *index, Some(*position), None)?;  }, GltfCreateImageOperation::Reorder { order } => { images_op(&mut next, GltfTopLevelFamily::Images, order[0], None, Some(order))?;  } } Ok(next) }
pub async fn encode(diff: &GltfCreateImageDiff) -> Result<Vec<u8>, GltfTopLevelMutationRejection> { serde_json::to_vec(diff).map_err(|error| reject("gltf.mutation.encode-failed", "diff", error.to_string())) }
pub async fn derive(payload: &GltfCreateImagePayload, base: &GltfSnapshot) -> Result<GltfCreateImageDiff, GltfTopLevelMutationRejection> { validate(payload, base)?; Ok(GltfCreateImageDiff { id: ID.into(), version: 1, touched_paths: touched_paths(payload), payload: payload.clone(), operation: operation(payload, base) }) }
pub async fn derive_transitional_gltf_diff(payload: &GltfCreateImagePayload, base: &GltfSnapshot) -> Result<GltfDiff, GltfTopLevelMutationRejection> { let next = apply(payload, base)?; Ok(family_diff(GltfTopLevelFamily::Images, base, &next)) }
